const fs = require('fs');
const files = ['a.txt','b.txt','c.txt'];
const expect = { 'a.txt': 12, 'b.txt': 18, 'c.txt': 30 };
let sum = 0;
const report = [];
for (const f of files) {
  const raw = fs.readFileSync(f, 'utf8');
  const trimmed = raw.trim();
  const m = trimmed.match(/^([A-Za-z]+) population:\s*(-?\d+)$/);
  if (!m) throw new Error(`unparseable source ${f}: ${JSON.stringify(raw)}`);
  const value = Number(m[2]);
  const ok = Number.isInteger(value) && value === expect[f] && trimmed === raw.trim();
  if (!ok) throw new Error(`cross-check failed for ${f}: parsed ${value}, expected ${expect[f]}`);
  sum += value;
  report.push({ file: f, label: m[1], value, bytes: fs.statSync(f).size, raw: JSON.stringify(raw) });
}
// independent recomputation of the sum
const recomputed = report.reduce((acc, r) => acc + r.value, 0);
if (recomputed !== sum) throw new Error('sum mismatch');
const answer = { total: sum };
if (typeof answer.total !== 'number' || !Number.isFinite(answer.total)) throw new Error('total is not numeric');
fs.writeFileSync('answer.json', JSON.stringify(answer) + '\n');

// post-write verification, reading the file back from disk
const readBack = JSON.parse(fs.readFileSync('answer.json', 'utf8'));
if (readBack.total !== 60) throw new Error('readback total mismatch: ' + readBack.total);
if (Object.keys(readBack).length !== 1 || !('total' in readBack)) throw new Error('answer.json keys wrong');
if (typeof readBack.total !== 'number') throw new Error('total must be numeric, got ' + typeof readBack.total);

console.log('per-source cross-check:', JSON.stringify(report));
console.log('sum =', sum, '| recomputed =', recomputed);
console.log('answer.json raw:', JSON.stringify(fs.readFileSync('answer.json','utf8')));
console.log('readback total:', readBack.total, 'typeof:', typeof readBack.total);
console.log('ALL CHECKS PASSED');
EOF
node --version && node crosscheck.js; echo "exit=$?"; echo '--- answer.json ---'; cat answer.json

cd /tmp/neutrino-fast-live-Kjebr5/multi_source_retrieval/fast_dag/1 && cat > verify_independent.js <<'EOF'
const fs = require('fs');
const path = require('path');
const files = ['a.txt','b.txt','c.txt'];
const fails = [];
const fail = m => { fails.push(m); console.log('FAIL: ' + m); };

// 1. literal read + independent extraction (different parser than crosscheck.js)
const values = {};
for (const f of files) {
  const p = path.resolve(f);
  const raw = fs.readFileSync(p, 'utf8');
  console.log(`[read] ${f} -> ${JSON.stringify(raw)}`);
  const lines = raw.split(/\r?\n/).filter(l => l.trim() !== '');
  if (lines.length !== 1) fail(`${f}: expected exactly 1 non-empty line, got ${lines.length}`);
  const line = lines[0];
  const m = line.match(/^[^:]*:\s*(-?\d+)\s*$/);
  if (!m) { fail(`${f}: line does not end with a single integer: ${JSON.stringify(line)}`); continue; }
  const v = Number(m[1]);
  if (!Number.isInteger(v)) fail(`${f}: not an integer: ${m[1]}`);
  values[f] = v;
  console.log(`[parse] ${f} population = ${v} (typeof ${typeof v}, int ${Number.isInteger(v)})`);
}
// also: no other numeric-looking strings in the number region surprises
for (const f of files) {
  const body = fs.readFileSync(f,'utf8');
  const nums = body.match(/-?\d+/g) || [];
  if (nums.length !== 1) fail(`${f}: expected exactly 1 numeric token in file, found ${nums.length}: ${JSON.stringify(nums)}`);
}

// 2. cross-check against independent expectation taken from the source wording
const expected = { 'a.txt': { name: 'Alpha', value: 12 }, 'b.txt': { name: 'Beta', value: 18 }, 'c.txt': { name: 'Gamma', value: 30 } };
for (const f of files) {
  const body = fs.readFileSync(f,'utf8');
  if (!body.startsWith(expected[f].name)) fail(`${f}: expected label ${expected[f].name}, got ${JSON.stringify(body)}`);
  if (values[f] !== expected[f].value) fail(`${f}: parsed ${values[f]} != expected ${expected[f].value}`);
  else console.log(`[crosscheck] ${f}: ${expected[f].name} -> ${values[f]} matches source text`);
}

// 3. sum computed three independent ways
let loopSum = 0; for (const f of files) loopSum += values[f];
const reduceSum = files.map(f => values[f]).reduce((x, y) => x + y, 0);
const bigSum = files.reduce((acc, f) => acc + BigInt(values[f]), 0n);
console.log(`[sum] loop=${loopSum} reduce=${reduceSum} bigint=${bigSum}`);
if (!(loopSum === reduceSum && BigInt(loopSum) === bigSum)) fail('sum methods disagree');

// 4. answer.json contract
const answerPath = path.resolve('answer.json');
if (!fs.existsSync(answerPath)) fail('answer.json missing');
else {
  const text = fs.readFileSync(answerPath, 'utf8');
  let obj;
  try { obj = JSON.parse(text); } catch (e) { fail('answer.json is not valid JSON: ' + e.message); }
  if (obj !== undefined) {
    const keys = Object.keys(obj);
    console.log(`[answer] raw=${JSON.stringify(text)} keys=${JSON.stringify(keys)} total=${obj.total} typeof=${typeof obj.total}`);
    if (keys.length !== 1 || keys[0] !== 'total') fail(`answer.json keys must be exactly ["total"], got ${JSON.stringify(keys)}`);
    if (typeof obj.total !== 'number') fail(`answer.json total must be numeric, got ${typeof obj.total}`);
    if (obj.total !== loopSum) fail(`answer.json total ${obj.total} != computed sum ${loopSum}`);
    if (!Number.isInteger(obj.total)) fail('answer.json total is not an integer');
  }
}
console.log(fails.length === 0 ? 'INDEPENDENT VERIFICATION PASSED' : `INDEPENDENT VERIFICATION FAILED (${fails.length})`);
process.exit(fails.length === 0 ? 0 : 1);
EOF
node verify_independent.js; echo "exit=$?"; echo "--- node version ---"; node --version

